INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3109, 'ተወዳጇ ልጅ', 'am', 'ናታቦ የምትወደው ገምቦ ስለተሰበረባት በጣም ተበሳጭታ ወደ ጫካ እየሮጠች ሄዳ ጠፋች፡፡ Nível: First words. Ilustração: Brian Wambi.', 'http://africanstorybook.org/illustrations/covers/20446.png', NULL, 1091, 25, 20, 'asp-20446', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3110, '7 የቀስተደመና ቀለማት', 'am', 'ይህ ተረት ቁጥሮችንና ቀለሞችን ለልጆች ያስተዋውቃል፡፡ (ተረቱን በሁለተኛ ደረጃ በተመደቡ ተረቶች ዝርዝር ውስጥም ማግኘት ይችላሉ፡፡) Nível: First words. Ilustração: Jesse Breytenbach.', 'http://africanstorybook.org/illustrations/covers/20447.png', NULL, 1091, 25, 20, 'asp-20447', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3111, 'እንቁራሪትና እባብ', 'am', 'አንዳንድ ጊዜ ጓደኝነት የራሱ የሆነ ገደብ እንዳለው የምንማርበትን ታሪክ እነሆ፡፡ Nível: First words. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/20451.png', NULL, 1091, 25, 20, 'asp-20451', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3112, 'Nhimbe', 'en', 'Nhimbe is a Zimbabwean custom where communities help each other doing work. The story focuses on the community helping Mbuya Sigauke weeding her field. Nível: Longer paragraphs. Ilustração: Blessing Nemadziva.', 'http://africanstorybook.org/illustrations/covers/20452.png', NULL, 734, 25, 20, 'asp-20452', 'cc-by', 0, NULL);
