INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3119, 'የኤሊ አፍንጫ ለምን ተጣመመ?', 'am', 'ወደ ጠብ ለመግባት እጅግ አትቸኩሉ፡፡ (ይህ ተረት በሦስተኛ ደረጃ ተረቶች ዝርዝርም ውስጥ አለ፡፡) Nível: First words. Ilustração: Marlene Visser.', 'http://africanstorybook.org/illustrations/covers/20480.png', NULL, 1091, 25, 20, 'asp-20480', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3120, 'ጅብ፣ ጥንቸልና ሳፋዎቻቸው', 'am', 'ሳፋ መውለድ ከቻለ፤ ሕይወት አለው ማለት ነው፡፡ ሕይወት ያላቸው ሁሉ ይሞታሉ፡፡ Nível: First words. Ilustração: lang:	Amharic.', 'http://africanstorybook.org/illustrations/covers/20481.png', NULL, 1091, 25, 20, 'asp-20481', 'cc-by', 0, NULL);
