INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3123, 'የእንቁራሪት ቆዳ', 'am', 'ይህ ተረት እንቁራሪቶች እንዴት ወጣገባ ያለ ሰውነት ሊኖራቸው እንደቻለና ከውኃ ርቀው መኖር እንደሚችሉ ያብራራል፡፡ Nível: First words. Ilustração: Rob Owen.', 'http://africanstorybook.org/illustrations/covers/20492.png', NULL, 1091, 25, 20, 'asp-20492', 'cc-by', 0, NULL);
INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3124, 'Ng''ichuch', 'ng’aturkana', 'Erai ekoi loko kidiama aronis angichuch. Nível: First sentences. Ilustração: Ethan Alberts, Wiehan de Jager, Rob Owen and Mango Tree.', 'http://africanstorybook.org/illustrations/covers/20494.png', NULL, 1093, 25, 20, 'asp-20494', 'cc-by', 0, NULL);
