INSERT OR IGNORE INTO livros (id, titulo, idioma, sinopse, capa_url, ano_publicacao, autor_id, categoria_id, fonte_id, fonte_id_externo, licenca, leituras, conteudo_texto) VALUES (3126, 'Atiakun Akiroit', 'ng’aturkana', 'Abu adakar totiaku akilokony eboyor kech. Nível: First paragraphs. Ilustração: Vusi Malindi.', 'http://africanstorybook.org/illustrations/covers/20496.png', NULL, 198, 25, 20, 'asp-20496', 'cc-by', 0, NULL);
